        }
      })();
      cur.style.transform = 'translate(700px,560px)';
      (async () => {
        await wait(1200);
        while (root.isConnected) {
          if (!idle() || busy) {
            await wait(400);
            continue;
          }
          reset();
          await seq([
            async () => {
              while (left > 0 && idle()) await wait(200);
              return idle();
            },
            () => press(rs, 0.5),
            rest(2000),
            () => press($('.diff'), 0.5),
            rest(500),
            () => aim(email, 0.6),
            () => typeInto(email, 'tomas@fernway.co'),
            () => press(go, 0.55),
            rest(3600),
          ]);
          await wait(500);
        }
      })();
    }

